import os,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
p=d+'/../../sessions/'+os.path.basename(d)+'.jsonl'
raw=open(p).read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',raw):
    k,h,w=m[1],int(m[2]),int(m[3])
    tail=raw[m.end():]; rows=[]
    for line in tail.split('\n'):
        row=line.split()
        if len(row)==w and all(x.isdigit() for x in row): rows.append([int(x) for x in row])
        else: break
    if len(rows)==h: G[k]=rows
